const payload = $input.first().json.body || {};
const event = payload.event || payload.events?.[0];
if (!event || event.type !== 'message' || event.message?.type !== 'text' || !event.replyToken) return [];
const question = String(event.message.text || '').trim().slice(0, 1000);
if (!question) return [];
return [{ json: { question, replyToken: event.replyToken, characters: [...question].length } }];

