const prepared = $('Build GPT Request').first().json;
const raw = $json.choices?.[0]?.message?.content;
if (typeof raw !== 'string') throw new Error('OpenAI response missing choices[0].message.content');
let parsed;
try { parsed = JSON.parse(raw); } catch { throw new Error('OpenAI response is not valid JSON'); }
const text = typeof parsed.reply === 'string' ? parsed.reply.trim() : '';
if (!text) throw new Error('OpenAI reply is blank');
const allowed = ['greeting','menu','price','availability','unknown'];
const intent = allowed.includes(parsed.intent) ? parsed.intent : 'unknown';
return { json: { lineBody: { replyToken: prepared.replyToken, messages: [{type:'text',text:text.slice(0,4000)}] }, anonymousLog: { intent, characters: prepared.characters } } };
